"""Evaluate changes to declared source dependencies."""

import json

_MISSING = {"kind": "missing"}


def _canonical_json(value):
    """Return a stable JSON representation without modifying the value."""
    return json.dumps(
        value,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
        allow_nan=False,
    )


def evaluate(request, policy):
    """Evaluate complete states of unique, non-ignored declared paths."""
    ignored = set(policy.get("ignored", ()))
    saved = request.get("saved", {})
    current = request.get("current", {})

    changed = []
    for path in set(request.get("declared", ())):
        if path in ignored:
            continue
        before = saved.get(path, _MISSING)
        after = current.get(path, _MISSING)
        if _canonical_json(before) != _canonical_json(after):
            changed.append(path)

    changed.sort()
    return {"needs_review": bool(changed), "changed": changed}

